Schema:
table:chat_conversation_instruction_legacy:CREATE TABLE chat_conversation_instruction_legacy (
 conversation_id TEXT PRIMARY KEY REFERENCES chat_conversations(id)
)

table:chat_natural_scans:CREATE TABLE chat_natural_scans (
 channel_ref TEXT PRIMARY KEY, cursor TEXT NOT NULL, high_water TEXT NOT NULL DEFAULT '', before_id TEXT NOT NULL DEFAULT ''
)

table:connector_owner:CREATE TABLE connector_owner (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1), owner_id INTEGER NOT NULL, generation INTEGER NOT NULL CHECK(generation>0)
)

table:doctor_repair_write_permits:CREATE TABLE doctor_repair_write_permits (
 repair_id TEXT PRIMARY KEY REFERENCES doctor_repairs(id)
)

table:managed_parent_closures:CREATE TABLE managed_parent_closures (
    parent_task TEXT PRIMARY KEY REFERENCES managed_features(parent_task) ON DELETE CASCADE
)

table:plan_archive_grants:CREATE TABLE plan_archive_grants (
    parent TEXT PRIMARY KEY
)

table:project_legacy_approver_eligibility:CREATE TABLE project_legacy_approver_eligibility (
 repo_id INTEGER PRIMARY KEY REFERENCES repos(id) ON DELETE CASCADE
)

table:report_delivery_legacy_runs:CREATE TABLE report_delivery_legacy_runs (
    run_id INTEGER PRIMARY KEY REFERENCES runs(id) ON DELETE CASCADE
)

table:standards_conversation_operations:CREATE TABLE standards_conversation_operations (
 operation_key TEXT PRIMARY KEY, record_json TEXT NOT NULL
)

table:submission_run_counters:CREATE TABLE submission_run_counters (
 run_id INTEGER PRIMARY KEY REFERENCES runs(id), sequence INTEGER NOT NULL DEFAULT 0, retained_bytes INTEGER NOT NULL DEFAULT 0
)

trigger:connector_owner_delete:CREATE TRIGGER connector_owner_delete AFTER DELETE ON identities
WHEN OLD.forge='github' AND OLD.role='owner'
BEGIN
 UPDATE connector_owner SET owner_id=0,generation=generation+1 WHERE singleton=1;
 UPDATE connector_grants SET revoked_at=COALESCE(revoked_at,OLD.derived_at),reason=COALESCE(reason,'owner_changed');
 DELETE FROM connector_browsers;
 DELETE FROM connector_codes;
END

trigger:connector_owner_insert:CREATE TRIGGER connector_owner_insert AFTER INSERT ON identities
WHEN NEW.forge='github' AND NEW.role='owner' AND COALESCE(NEW.user_id,0)<>(SELECT owner_id FROM connector_owner WHERE singleton=1)
BEGIN
 UPDATE connector_owner SET owner_id=COALESCE(NEW.user_id,0), generation=generation+1 WHERE singleton=1;
 UPDATE connector_grants SET revoked_at=COALESCE(revoked_at,NEW.derived_at),reason=COALESCE(reason,'owner_changed');
 DELETE FROM connector_browsers;
 DELETE FROM connector_codes;
END

trigger:connector_owner_update:CREATE TRIGGER connector_owner_update AFTER UPDATE OF user_id ON identities
WHEN NEW.forge='github' AND NEW.role='owner' AND COALESCE(NEW.user_id,0)<>(SELECT owner_id FROM connector_owner WHERE singleton=1)
BEGIN
 UPDATE connector_owner SET owner_id=COALESCE(NEW.user_id,0), generation=generation+1 WHERE singleton=1;
 UPDATE connector_grants SET revoked_at=COALESCE(revoked_at,NEW.derived_at),reason=COALESCE(reason,'owner_changed');
 DELETE FROM connector_browsers;
 DELETE FROM connector_codes;
END
